def declarar_conservacion(apps, schema_editor):
    """Lo que requiere frío declara su límite: −18 °C lo congelado, 4 °C lo refrigerado."""
    Producto = apps.get_model('webcitt', 'Producto')
    congelado = re.compile(r'congelad|helad|paleta', re.IGNORECASE)
    for producto in Producto.objects.filter(requiere_frio=True, temperatura_maxima=None).select_related('familia'):
        familia = producto.familia.nombre if producto.familia_id else ''
        producto.temperatura_maxima = Decimal('-18') if congelado.search(f'{producto.nombre} {familia}') else Decimal('4')
        producto.save(update_fields=['temperatura_maxima'])


